#!/usr/bin/env node
// Verifies Data Matrix codes generated by src/components/data-matrix.tsx are
// structurally valid (decodable) using an independent decoder.
//
// KNOWN LIMITATION: the `datamatrix-decode` package only implements ASCII-mode
// decoding, not C40/EDIFACT. datamatrix-svg-ts auto-selects the most efficient
// mode based on content, and our real generateCodigo() output (~14 chars,
// e.g. "FL-MTMCY1WZ756") falls into C40, which this decoder can't read —
// that's a decoder limitation, not evidence the encoded pattern is wrong.
// So this script verifies short ASCII-mode-eligible strings (proving the
// matrix structure, quiet zone, and timing pattern are standard-compliant)
// plus one real-shaped code where we only assert the pattern *encodes*
// without throwing, not that this decoder can read it back.
//
// This does NOT prove a phone camera can read a printed copy — that needs a
// real-device test with expo-camera.
//
// Not a Jest test: datamatrix-svg-ts ships ESM-only and Jest's default config
// in this project doesn't transform node_modules, so it can't be imported from
// a .test.ts file. Run directly: node scripts/verify-datamatrix.mjs

import { encodeToMatrix } from 'datamatrix-svg-ts';
import decode from 'datamatrix-decode';

function generateCodigo() {
  return `FL-${Date.now().toString(36).toUpperCase()}${Math.floor(Math.random() * 36 ** 3)
    .toString(36)
    .toUpperCase()
    .padStart(3, '0')}`;
}

function toBits(value) {
  const { matrix, width, height } = encodeToMatrix(value);
  // matrix rows are sparse arrays (off cells are holes, not 0) — materialize them.
  const bits = matrix.map((row) => Array.from({ length: width }, (_, x) => (row[x] ? 1 : 0)));
  if (bits.length !== height) throw new Error(`row count ${bits.length} != height ${height}`);
  return bits;
}

let failures = 0;

console.log('--- ASCII-mode round-trip (verifies structure end-to-end) ---');
for (const value of ['A', '12', 'FL1', 'FL-MTMCY1']) {
  try {
    const decoded = decode(toBits(value));
    if (decoded !== value) {
      console.error(`FAIL: encoded "${value}" but decoded back as "${decoded}"`);
      failures++;
    } else {
      console.log(`OK: "${value}"`);
    }
  } catch (err) {
    console.error(`FAIL: "${value}" threw: ${err.message}`);
    failures++;
  }
}

console.log('\n--- Real-shaped codes (encode-only smoke check, C40 not decodable here) ---');
for (const value of [generateCodigo(), generateCodigo(), generateCodigo()]) {
  try {
    toBits(value);
    console.log(`OK (encodes without error): "${value}"`);
  } catch (err) {
    console.error(`FAIL: "${value}" threw: ${err.message}`);
    failures++;
  }
}

if (failures > 0) {
  console.error(`\n${failures} case(s) failed.`);
  process.exit(1);
}
console.log('\nAll checks passed.');
